```c++
#include <iostream>
#include <fstream>
#include <string>
#include <unordered_map>

using namespace std;

int main() {
    string wordToCount; // Слово, для которого необходимо подсчитать вхождения
    cout << "Enter the word to count: ";
    cin >> wordToCount;

    string fileName;
    cout << "Enter the file name: ";
