        return 1;
    }

    // Словарь для подсчета вхождений
    unordered_map<string, int> wordCount;

    // Чтение файла построчно и подсчет вхождений слова
    string line;
    while (getline(file, line)) {
        // Считать количество вхождений слова в строке
        size_t count = count(line.begin(), line.end(), wordToCount);

        // Обновить подсчет вхождений слова в словаре
        wordCount[wordToCount] += count;
